def throttle(rate=10, period=1.0):
    """Throttles the decorated function to at most `rate` calls per `period` seconds.

    Args:
        rate: Maximum number of calls allowed per period
        period: Time period in seconds (can be a timedelta or numeric)

    Returns:
        Decorator function that throttles calls
    """
    if isinstance(period, timedelta):
        period = period.total_seconds()

    def decorator(f):
        import time

        last_call_time = [None]
        call_count = [0]

        @wraps(f)
        def wrapper(*args, **kwargs):
            now = time.monotonic()

            if last_call_time[0] is None:
                # First call - proceed
                last_call_time[0] = now
                call_count[0] = 1
                return f(*args, **kwargs)

            elapsed = now - last_call_time[0]

            if elapsed >= period:
                # Period expired, reset
                last_call_time[0] = now
                call_count[0] = 1
                return f(*args, **kwargs)
            else:
                # Still within period
                if call_count[0] < rate:
                    call_count[0] += 1
                    return f(*args, **kwargs)
                else:
                    # Rate limit exceeded
                    raise ErrorRateExceeded("Rate limit exceeded")

        return wrapper

    return decorator

